gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

# Define GSLFunction class
class GSLFunction:
    def __init__(self, func):
        self.func = func
        self.callback = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(self._callback)

    def _callback(self, x):
        return self.func(x)

# Define CQuadWorkspace class
class CQuadWorkspace:
    def __init__(self, size):
        self.size = size
        self.workspace = gsl.gsl_integration_cquad_workspace_alloc(size)

    def __del__(self):
        if self.workspace is not None:
            gsl.gsl_integration_cquad_workspace_free(self.workspace)

# Define integrate_function function
def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    gsl_func = GSLFunction(func)
    result = ctypes.c_double()
    abserr = ctypes.c_double()
    neval = ctypes.c_size_t()
    workspace = CQuadWorkspace(workspace_size)

    status = gsl.gsl_integration_cquad(gsl_func.callback, a, b, epsabs, epsrel,
                                        ctypes.byref(result), ctypes.byref(abserr),
                                        ctypes.byref(neval), workspace.workspace)

    if status != 0:
        raise ValueError(f"Integration failed with status {status}")

    return result.value, abserr.value, neval.value

