    def integrate_with_singularity(self, func, a, b, c):
        result = ctypes.c_double()
        abserr = ctypes.c_double()
        flag = ctypes.c_int()
        gsl.gsl_integration_qc25c.restype = ctypes.c_int
        status = gsl.gsl_integration_qc25c(func, ctypes.byref(ctypes.c_double(a)), ctypes.byref(ctypes.c_double(b)), ctypes.byref(ctypes.c_double(c)), self.wrapper, None, ctypes.byref(result), ctypes.byref(abserr), ctypes.byref(flag))
