class GSLFunction:
    def __init__(self, func):
        self.func = func

    def wrapper(self, x, params):
        return self.func(x, *params)

    def __call__(self, x, *params):
        return self.wrapper(x, params)

def integrate_with_singularity(func, a, b, c):
    gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    func_obj = GSLFunction(func)
    params = (ctypes.c_double * len(params))(*params)
    wrapper_func = func_obj.wrapper
    wrapper_func.restype = ctypes.c_double
    wrapper_func.argtypes = [ctypes.c_double]

    gsl.gsl_integration_qc25c.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.c_void_p, ctypes.c_double, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_int)]

    result = ctypes.c_double(0.0)
    abserr = ctypes.c_double(0.0)
    iest = ctypes.c_int(0)

    gsl.gsl_integration_qc25c(wrapper_func, a, b, ctypes.byref(params), ctypes.byref(abserr), ctypes.byref(iest))

    return result.value, abserr.value, iest.value

