class GSLFunction:
    def __init__(self, func):
        self.func = func
        self.callback = gsl.GSL_FUNCTION_TYPE(self.c_wrapper)

    def c_wrapper(self, x, params):
        return ctypes.c_double(self.func(x.value))

def integrate_qk31(func, a, b):
    f = GSLFunction(func)
    result = ctypes.c_double(0.0)
