class GSLMatrix:
    def __init__(self, matrix):
        self.rows = len(matrix)
        self.cols = len(matrix[0])
        self.data = (ctypes.c_double * self.rows * self.cols)(*sum(matrix, []))

    @property
def gsl_matrix_minmax_index(self):
        func = gsl.gsl_matrix_minmax_index
        func.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_size_t, ctypes.c_size_t]
        func.restype = None
        min_index = ctypes.c_size_t()
        max_index = ctypes.c_size_t()
        func(self.data, self.rows, self.cols, ctypes.byref(min_index), ctypes.byref(max_index))
        return (min_index.value // self.cols, min_index.value % self.cols), (max_index.value // self.cols, max_index.value % self.cols)

def find_minmax_indices(matrix):
    gsl_matrix = GSLMatrix(matrix)
    return gsl_matrix.gsl_matrix_minmax_index

