NIEDERREITER_2 = 1
GSL_SUCCESS = 0

class gsl_qrng_state(ctypes.Structure):
    _fields_ = ["type", "dimension", "state"]

def generate_niederreiter_point(dimension):
    if dimension < 1 or dimension > 12:
        raise ValueError("Dimension must be between 1 and 12")

    state_ptr = gsl.gsl_qrng_alloc(NIEDERREITER_2, dimension)
    if not state_ptr:
        raise MemoryError("Failed to allocate GSL quasi-random number generator")

    result = (ctypes.c_double * dimension)()
    status = gsl.gsl_qrng_get(state_ptr, result)
    if status != GSL_SUCCESS:
        raise RuntimeError(f"GSL error: {status}")

    gsl.gsl_qrng_free(state_ptr)

    return tuple(result[:dimension])

