from typing import List, Tuple

class GSLFunction:
    def __init__(self):
        self.f = self.create_callback()

    @staticmethod
def create_callback() -> ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_void_p)):
        return ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_void_p))(
            lambda x, params: math.sin(x) + math.cos(2*x)
        )

    def compute_chebyshev_approximations(self) -> List[Tuple[float, float, float, float]]:
        libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        n = 10000
        a, b = 0.0, 1.0
        x = (ctypes.c_double * n)()
        y = (ctypes.c_double * n)()

        for i in range(n):
            x[i] = a + (b - a) * i / (n - 1)

        cheb_workspace = gsl.gsl_cheb_alloc(40)
        if not cheb_workspace:
            raise RuntimeError("Failed to allocate Chebyshev workspace")

        gsl.gsl_cheb_init(cheb_workspace, self.f, ctypes.byref(ctypes.c_void_p()), a, b)

        r10 = (ctypes.c_double * n)()
        r40 = (ctypes.c_double * n)()

        for i in range(n):
            y[i] = gsl.gsl_cheb_eval_n(cheb_workspace, 10, x[i])
            r10[i] = y[i]
            y[i] = gsl.gsl_cheb_eval_n(cheb_workspace, 40, x[i])
            r40[i] = y[i]

        results = [(x[i], self.f(x[i], None), r10[i], r40[i]) for i in range(n)]
        gsl.gsl_cheb_free(cheb_workspace)
        return results

