import ctypes

class GSLPolyComplexWorkspace:
    def __init__(self, degree):
        self.degree = degree
        self.workspace = gsl.gsl_poly_complex_workspace_alloc(degree)

    def free(self):
        gsl.gsl_poly_complex_workspace_free(self.workspace)

def compute_complex_roots(coefficients):
    if not coefficients or len(coefficients) < 2:
        raise ValueError('At least two coefficients are required')

    degree = len(coefficients) - 1
    roots = (ctypes.c_double * (degree * 2))()
    workspace = GSLPolyComplexWorkspace(degree)

    try:
        status = gsl.gsl_poly_complex_solve(
            (ctypes.c_double * len(coefficients))(*coefficients),
            degree,
            roots,
            workspace.workspace
        )
        if status != 0:
            raise RuntimeError('Error solving polynomial roots')

        return [complex(roots[i*2], roots[i*2+1]) for i in range(degree)]
    finally:
        workspace.free()

