class GSLMatrix:
    def __init__(self, matrix):
        self.n = len(matrix)
        self.data = (ctypes.c_double * self.n * self.n)()
        for i in range(self.n):
            for j in range(self.n):
                self.data[i * self.n + j] = matrix[i][j]

    def __getitem__(self, index):
        return self.data[index[0] * self.n + index[1]]

    def __setitem__(self, index, value):
        self.data[index[0] * self.n + index[1]] = value

    @property
    def array(self):
        return (ctypes.c_double * self.n * self.n).from_address(ctypes.addressof(self.data))

class GSLPermutation:
    def __init__(self, n):
        self.p = (ctypes.c_int * n)()
        for i in range(n):
            self.p[i] = i

    @property
    def array(self):
        return (ctypes.c_int * len(self.p)).from_address(ctypes.addressof(self.p))

def lu_decomposition(matrix):
    n = len(matrix)
    gsl_matrix = GSLMatrix(matrix)
    gsl_permutation = GSLPermutation(n)
    signum = ctypes.c_int()

    gsl.gsl_linalg_LU_decomp(gsl_matrix.array, ctypes.byref(ctypes.c_size_t(n)), gsl_permutation.array)

    lu_matrix = [[gsl_matrix[i][j] for j in range(n)] for i in range(n)]
    permutation = [gsl_permutation.p[i] for i in range(n)]

    return {'LU_decomposed_matrix': lu_matrix, 'permutation_vector': permutation, 'signum': signum.value}

