GSLMatrix = ctypes.c_void_p

def create_gsl_matrix(rows, cols):
    return gsl.gsl_matrix_alloc(rows, cols)

def extract_matrix(gsl_mat):
    data = (ctypes.c_double * rows * cols).from_address(gsl_mat.contents.data)
    matrix = [[data[row*cols + col] for col in range(cols)] for row in range(rows)]
    return matrix

def apply_givens_qr(Q, R, i, j, c, s):
    M, N = len(Q), len(R[0])
    Q_ptr = create_gsl_matrix(M, N)
    R_ptr = create_gsl_matrix(N, N)
    for row in range(M):
        for col in range(N):
            gsl.gsl_matrix_set(Q_ptr, row, col, Q[row][col])
    for row in range(N):
        for col in range(N):
            gsl.gsl_matrix_set(R_ptr, row, col, R[row][col])
    gsl.apply_givens_qr(M, N, Q_ptr, R_ptr, i, j, c, s)
    modified_Q = extract_matrix(Q_ptr)
    modified_R = extract_matrix(R_ptr)
    gsl.gsl_matrix_free(Q_ptr)
    gsl.gsl_matrix_free(R_ptr)
    return modified_Q, modified_R

