import ctypes

gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class GSLFunction:
    def __init__(self, function):
        self.function = function
        self.c_function = self._create_c_function()

    def _create_c_function(self):
        c_func = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_void_p))
        return c_func(self._wrapper)

    def _wrapper(self, x, params):
        args = [x] + [ctypes.byref(p) for p in params]
        return self.function(*args)

    def get_c_function(self):
        return self.c_function

class GSLMinFMinimizer:
    def __init__(self, function, initial_params=None, step=1.0):
        self.function = function.get_c_function()
        self.initial_params = initial_params if initial_params is not None else [ctypes.c_double(0)] * 6
        self.step = ctypes.c_double(step)
        self.minimizer_type = gsl.GSL_MIN_FMINIMIZER_BRENT
        self.minimizer = gsl.gsl_min_fminimizer_alloc(self.minimizer_type)
        self.status = gsl.GSL_SUCCESS

    def setup(self, x_minimum, f_minimum, x_lower, f_lower, x_upper, f_upper):
        self.x_minimum = ctypes.c_double(x_minimum)
        self.f_minimum = ctypes.c_double(f_minimum)
        self.x_lower = ctypes.c_double(x_lower)
        self.f_lower = ctypes.c_double(f_lower)
        self.x_upper = ctypes.c_double(x_upper)
        self.f_upper = ctypes.c_double(f_upper)
        self.params = (ctypes.c_double * 6)(x_minimum, f_minimum, x_lower, f_lower, x_upper, f_upper)
        gsl.gsl_min_fminimizer_set(self.minimizer, self.function, ctypes.byref(self.x_minimum), self.step, ctypes.byref(self.x_lower), ctypes.byref(self.f_lower), ctypes.byref(self.x_upper), ctypes.byref(self.f_upper))

    def iterate(self):
        self.status = gsl.gsl_min_fminimizer_iterate(self.minimizer)
        if self.status != 0:
            raise RuntimeError("Minimizer failed with status: {}".format(self.status))
        return (
            self.minimizer.x.contents.value,
            self.minimizer.fmin.contents.value,
            self.minimizer.lower.contents.value,
            self.minimizer.flower.contents.value,
            self.minimizer.upper.contents.value,
            self.minimizer.fupper.contents.value,
        )

    def get_minimum(self):
        return (
            self.minimizer.x.contents.value,
            self.minimizer.fmin.contents.value,
        )

    def free(self):
        gsl.gsl_min_fminimizer_free(self.minimizer)

# Example usage
if __name__ == "__main__":
    def my_function(x, params):
        return x ** 2 - 3 * x + 1

    function = GSLFunction(my_function)
    minimizer = GSLMinFMinimizer(function)
    minimizer.setup(0.5, my_function(0.5), 0.0, my_function(0.0), 1.0, my_function(1.0))
    updated_values = minimizer.iterate()
    print(updated_values)

