        self.func = func
        self.f = self.create_func()

    def create_func(self):
        f = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_void_p))
        return f(self.wrapper)

    def wrapper(self, x, params):
        return self.func(x, params.contents.params)

def integrate_function(f, a, b, epsabs, epsrel, limit):
    workspace = gsl.gsl_integration_workspace_alloc(limit)
    result = ctypes.c_double(0.0)
    abserr = ctypes.c_double(0.0)
    status = gsl.gsl_integration_qags(f.f, a, b, epsabs, epsrel, limit, workspace, ctypes.byref(result), ctypes.byref(abserr))
    gsl.gsl_integration_workspace_free(workspace)
    if status != 0:
        raise Exception("Integration failed with status: " + str(status))
    return result.value, abserr.value

