def matrix_to_gsl(matrix):
    rows = len(matrix)
    cols = len(matrix[0])
    gsl_matrix_ptr = gsl_matrix_p((rows * cols * ctypes.sizeof(GSLMatrix))
    for i in range(rows):
        for j in range(cols):
            gsl_matrix_ptr[i*cols + j] = matrix[i][j]
    return gsl_matrix_ptr, rows, cols

def gsl_matrix_to_numpy(gsl_matrix, rows, cols):
    numpy_matrix = [[0.0 for _ in range(cols)] for _ in range(rows)]
    for i in range(rows):
        for j in range(cols):
            numpy_matrix[i][j] = gsl_matrix[i*cols + j]
    return numpy_matrix

def compute_matrix_exponential(matrix, mode):
    try:
        gsl_matrix_ptr, rows, cols = matrix_to_gsl(matrix)
        if rows != cols:
            raise ValueError("Input matrix must be square")
        result = gsl.gsl_linalg_exponential_ss(gsl_matrix_ptr, ctypes.c_int(mode))
        if result != 0:
            raise RuntimeError(f"Error in computing matrix exponential (gsl error code: {result})")
        return gsl_matrix_to_numpy(gsl_matrix_ptr, rows, cols)
