def matrix_to_gsl(matrix):
    nrows, ncols = len(matrix), len(matrix[0])
    gsl_matrix = gsl.gsl_matrix_d(nrows, ncols)
    for i in range(nrows):
        for j in range(ncols):
            gsl.gsl_matrix_set(gsl_matrix, i, j, matrix[i][j])
    return gsl_matrix

def gsl_matrix_to_numpy(gsl_matrix):
    nrows = gsl.gsl_matrix_d_get_rows(gsl_matrix)
    ncols = gsl.gsl_matrix_d_get_cols(gsl_matrix)
    result = [[0.0 for _ in range(ncols)] for _ in range(nrows)]
    for i in range(nrows):
        for j in range(ncols):
            result[i][j] = gsl.gsl_matrix_get(gsl_matrix, i, j)
    return result

def compute_matrix_exponential(matrix, mode):
    nrows, ncols = len(matrix), len(matrix[0])
    if nrows != ncols:
        raise ValueError("Input matrix must be square")

    gsl_matrix = matrix_to_gsl(matrix)
    exp_matrix = gsl.gsl_matrix_d(nrows, ncols)

    status = gsl.gsl_linalg_exponential_ss(gsl_matrix, mode, exp_matrix)
    if status != 0:
        raise RuntimeError("Error computing matrix exponential")

    result = gsl_matrix_to_numpy(exp_matrix)
    return result

