def next_combination(current_combination, n):
    size = len(current_combination)
    data = (ctypes.c_size_t * size)(*current_combination)
    comb = gsl.gsl_combination_calloc(size, n)
    if not comb:
        raise RuntimeError("Failed to allocate GSL combination")
    try:
        ctypes.memmove(comb.data, data, size * ctypes.sizeof(ctypes.c_size_t))
        if gsl.gsl_combination_next(comb) == 0:
            return tuple(comb.data[:size])
        else:
            return None
    finally:
