    current_arr = (ctypes.c_long * len(current_combination))(*current_combination)
    comb = gsl_combination(data=current_arr, size=len(current_combination), stride=1)
    if gsl.gsl_combination_next(ctypes.byref(comb), n) == 0:
        return tuple(comb.data[:comb.size])
    else:
