class GSLMatrix(ctypes.Structure):
    _fields_ = [
        ("size1", ctypes.c_size_t),
        ("size2", ctypes.c_size_t),
        ("tda", ctypes.c_size_t),
        ("data", ctypes.POINTER(ctypes.c_double))
    ]

def allocate_matrix(rows, cols):
    data = (ctypes.c_double * (rows * cols))()
    return GSLMatrix(rows, cols, cols, data)

def set_matrix_values(matrix, values):
    for i in range(matrix.size1):
        for j in range(matrix.size2):
            matrix.data[i * matrix.tda + j] = values[i][j]

def get_matrix_values(matrix):
    return [[matrix.data[i * matrix.tda + j] for j in range(matrix.size2)] for i in range(matrix.size1)]

def transpose_matrix(matrix):
    gsl.gsl_matrix_transpose.argtypes = [ctypes.POINTER(GSLMatrix)]
    gsl.gsl_matrix_transpose.restype = None
    gsl.gsl_matrix_transpose(ctypes.byref(matrix))

# Example usage:
