import ctypes
ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class GSLMatrix(ctypes.Structure):
    _fields_ = [
        ("data", ctypes.POINTER(ctypes.c_double)),
        ("size1", ctypes.c_size_t),
        ("size2", ctypes.c_size_t)
    ]

def transpose_matrix(matrix:
    rows = len(matrix)
    cols = len(matrix[0])
    data = (ctypes.c_double * (rows * cols))()
    for i in range(rows):
        for j in range(cols):
            data[i + j * rows] = matrix[j][i]

    gsl_matrix = GSLMatrix(data, rows, cols)
    gsl.gsl_matrix_transpose(ctypes.byref(gsl_matrix))

    transposed_matrix = [[0 for _ in range(rows)] for _ in range(cols)]
    for i in range(rows):
        for j in range(cols):
            transposed_matrix[j][i] = data[i + j * rows]

    return transposed_matrix

