    if not all(xrange[i] < xrange[i + 1] for i in range(len(xrange) - 1)):
        raise ValueError("xrange must be in increasing order")
    if not all(yrange[i] < yrange[i + 1] for i in range(len(yrange) - 1)):
        raise ValueError("yrange must be in increasing order")

