def create_histogram2d(nx, ny, xrange, yrange):
    if not isinstance(nx, int) or nx <= 0:
        raise ValueError('nx must be a positive integer')
    if not isinstance(ny, int) or ny <= 0:
        raise ValueError('ny must be a positive integer')
    if not all(isinstance(x, float) for x in xrange):
        raise ValueError('xrange must be a list of doubles')
    if not all(isinstance(y, float) for y in yrange):
        raise ValueError('yrange must be a list of doubles')
    if not (len(xrange) == nx + 1 and len(yrange) == ny + 1):
        raise ValueError('xrange and yrange must have the correct length')
    gsl_histogram2d_calloc_range = gsl.gsl_histogram2dcalloc_range
    gsl_histogram2d_calloc_range.argtypes = [ctypes.c_size_t, ctypes.c_size_t, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]
    gsl_histogram2d_calloc_range.restype = ctypes.POINTER(gsl.gsl_histogram2d)
    xarray = (ctypes.c_double * (nx + 1))(*xrange)
    yarray = (ctypes.c_double * (ny + 1))(*yrange)
    result = gsl_histogram2d_calloc_range(nx, ny, ctypes.byref(xarray), ctypes.byref(yarray))
    if not result:
        raise RuntimeError('Failed to allocate histogram')
    return result

