def validate_input(vector_x, vector_y):
    if not (isinstance(vector_x, list) and isinstance(vector_y, list)):
        raise ValueError("Both inputs must be lists.")
    if len(vector_x) != len(vector_y):
        raise ValueError("Input vectors must have the same length.")
    for element in vector_x + vector_y:
        if not isinstance(element, (int, float)):
            raise ValueError("All elements of the input vectors must be numbers.")

def compute_dot_product(vector_x, vector_y):
    gsl = load_gsl_libraries()
