    x_array = (ctypes.c_double * len(vector_x))(*vector_x)
    y_array = (ctypes.c_double * len(vector_y))(*vector_y)
    result = gsl.cblas_ddot(len(vector_x), x_array, 1, y_array, 1)
    return float(result)

