def compute_bessel_jl(l, x):
    l_type = ctypes.c_int
    x_type = ctypes.c_double
    result_type = gsl.sf_bessel_jl_e.argtypes[2]

    bessel_func = gsl.sf_bessel_jl_e
    bessel_func.argtypes = [l_type, x_type, ctypes.POINTER(result_type)]
    bessel_func.restype = ctypes.c_int

    result_ptr = result_type()
    status = bessel_func(l, x, ctypes.byref(result_ptr))

    if status != 0:
        raise Exception(f"Error computing Bessel function: {status}")

    return GSLResult(result_ptr.val)

